CREATE TABLE `account_listings` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `seller_id` int unsigned NOT NULL,
  `game_id` int unsigned NOT NULL,
  `platform_id` int unsigned NOT NULL,
  `squad_scan_id` int unsigned DEFAULT NULL,
  `valuation_id` int unsigned DEFAULT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `asking_price` decimal(12,2) NOT NULL,
  `fair_price_min` decimal(12,2) DEFAULT NULL,
  `fair_price_max` decimal(12,2) DEFAULT NULL,
  `value_badge` enum('GREAT_VALUE','FAIR','OVERPRICED') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `team_strength` smallint unsigned DEFAULT NULL,
  `image_urls` json DEFAULT NULL,
  `status` enum('DRAFT','SCANNING','SCAN_FAILED','PENDING_REVIEW','ACTIVE','RESERVED','SOLD','CANCELLED','SUSPENDED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `suspended_reason` text COLLATE utf8mb4_unicode_ci,
  `view_count` int unsigned DEFAULT '0',
  `sold_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `game_id` (`game_id`),
  KEY `platform_id` (`platform_id`),
  KEY `squad_scan_id` (`squad_scan_id`),
  KEY `valuation_id` (`valuation_id`),
  KEY `idx_listings_seller` (`seller_id`),
  KEY `idx_listings_status` (`status`),
  KEY `idx_listings_price` (`asking_price`),
  KEY `idx_listings_strength` (`team_strength`),
  KEY `idx_listings_created` (`created_at`),
  CONSTRAINT `account_listings_ibfk_1` FOREIGN KEY (`seller_id`) REFERENCES `users` (`id`),
  CONSTRAINT `account_listings_ibfk_2` FOREIGN KEY (`game_id`) REFERENCES `games` (`id`),
  CONSTRAINT `account_listings_ibfk_3` FOREIGN KEY (`platform_id`) REFERENCES `platforms` (`id`),
  CONSTRAINT `account_listings_ibfk_4` FOREIGN KEY (`squad_scan_id`) REFERENCES `squad_scans` (`id`) ON DELETE SET NULL,
  CONSTRAINT `account_listings_ibfk_5` FOREIGN KEY (`valuation_id`) REFERENCES `valuations` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=180 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
