  `room_id` int unsigned NOT NULL,
  `user_id` int unsigned NOT NULL,
  `action` enum('ROOM_OPENED','INFO_SUBMITTED','INFO_VIEWED','CONFIRMED','DISPUTE_OPENED','ROOM_CLOSED') COLLATE utf8mb4_unicode_ci NOT NULL,
  `ip_address` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_handover_logs_room` (`room_id`),
  KEY `idx_handover_logs_user` (`user_id`),
  CONSTRAINT `handover_access_logs_ibfk_1` FOREIGN KEY (`room_id`) REFERENCES `handover_rooms` (`id`) ON DELETE CASCADE,
  CONSTRAINT `handover_access_logs_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=140 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
