INSERT INTO `platform_settings` VALUES (1,'platform_fee_rate','0.05','อัตราค่าธรรมเนียมคนกลาง Platform (5%)',175,'2026-09-21 14:40:07'),(2,'payment_deadline_hours','2','ระยะเวลาที่ผู้ซื้อต้องชำระเงินก่อนคำสั่งซื้อหมดอายุ (ชั่วโมง)',1,'2026-09-21 11:09:10'),(3,'handover_timeout_hours','72','ระยะเวลาสูงสุดที่ผู้ขายต้องส่งมอบรหัสก่อนระบบยกเลิกและคืนเงิน (ชั่วโมง)',1,'2026-09-21 11:09:10'),(4,'buyer_confirm_deadline_hours','24','ระยะเวลาที่ผู้ซื้อต้องเข้าตรวจสอบบัญชีก่อนเริ่มแจ้งเตือน (ชั่วโมง)',1,'2026-09-21 11:09:10'),(5,'auto_release_hours','48','ระยะเวลาที่ระบบจะปล่อยเงินอัตโนมัติหากผู้ซื้อไม่ดำเนินการใดๆ (ชั่วโมง)',1,'2026-09-21 11:09:10'),(6,'dispute_sla_hours','48','ระยะเวลา SLA ในการตัดสินข้อพิพาทของทีมงาน (ชั่วโมง)',1,'2026-09-21 11:09:10'),(7,'badge_great_value_threshold','0.85','เกณฑ์ป้ายคุ้มค่ามาก: ราคาขาย <= 85% ของ Fair Price',1,'2026-09-21 11:09:10'),(8,'badge_overpriced_threshold','1.15','เกณฑ์ป้ายแพงเกิน: ราคาขาย > 115% ของ Fair Price',1,'2026-09-21 11:09:10');
