/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `player_cards` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `game_id` int unsigned NOT NULL,
  `efhub_id` bigint unsigned DEFAULT NULL,
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `player_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `card_tier_id` int unsigned NOT NULL,
  `position_id` int unsigned NOT NULL,
  `nationality` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `club` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `overall_rating` tinyint unsigned NOT NULL,
  `base_value` decimal(15,2) DEFAULT '0.00',
  `is_active` tinyint(1) DEFAULT '1',
  `season` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `efhub_id` (`efhub_id`),
  KEY `game_id` (`game_id`),
  KEY `position_id` (`position_id`),
  KEY `idx_player_cards_name` (`player_name`),
  KEY `idx_player_cards_tier` (`card_tier_id`),
  KEY `idx_player_cards_rating` (`overall_rating`),
  CONSTRAINT `player_cards_ibfk_1` FOREIGN KEY (`game_id`) REFERENCES `games` (`id`),
  CONSTRAINT `player_cards_ibfk_2` FOREIGN KEY (`card_tier_id`) REFERENCES `card_tiers` (`id`),
  CONSTRAINT `player_cards_ibfk_3` FOREIGN KEY (`position_id`) REFERENCES `positions` (`id`),
  CONSTRAINT `player_cards_chk_1` CHECK ((`overall_rating` between 1 and 125))
) ENGINE=InnoDB AUTO_INCREMENT=920 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

